using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class OffshoreNavigationCliffs{const string D="Assets/Scenes/Oasis/SouthBeach/OffshoreLandmarks",B="Assets/Scenes/Oasis/SouthBeach/BeachDetails";static Type T=typeof(ReferenceWorkingMarina).GetNestedType("Geo",BindingFlags.NonPublic);static object g;static void Pole(Vector3 a,Vector3 b,float r,Color c,int sides=12){T.GetMethod("Pole").Invoke(g,new object[]{a,b,r,-1,c,sides});}static void Box(Vector3 p,Vector3 s,Color c,float glow=0){T.GetMethod("Box").Invoke(g,new object[]{p,s,-1,c,glow});}static void Tri(Vector3 a,Vector3 b,Vector3 c,Color color){T.GetMethod("Tri").Invoke(g,new object[]{a,b,c,-1,color,0f});}static OffshoreNavigationCliffs(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("OffshoreNavigationCliffs.request"))return;File.Delete("OffshoreNavigationCliffs.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/OffshoreNavigationCliffs.txt",e.ToString());}}
static Mesh Tower(bool far){g=Activator.CreateInstance(T);var top=new Vector3(1,24.5f,0);if(far)Pole(top,top+Vector3.up*13,1.35f,Color.white,6);else{for(int k=0;k<4;k++)Pole(top+Vector3.up*(k*3),top+Vector3.up*(k*3+3),1.5f-k*.12f,k%2==0?new Color(.91f,.90f,.82f):new Color(.6f,.14f,.075f));Pole(top+Vector3.up*12,top+Vector3.up*12.3f,2,new Color(.2f,.23f,.22f));for(int k=0;k<12;k++){float a=k*Mathf.PI/6,b=(k+1)*Mathf.PI/6;var u=top+new Vector3(Mathf.Cos(a)*1.9f,12.3f,Mathf.Sin(a)*1.9f);var v=top+new Vector3(Mathf.Cos(b)*1.9f,12.3f,Mathf.Sin(b)*1.9f);Pole(u,u+Vector3.up*.8f,.045f,new Color(.12f,.15f,.15f),4);Pole(u+Vector3.up*.8f,v+Vector3.up*.8f,.035f,new Color(.12f,.15f,.15f),4);}}Pole(top+Vector3.up*12.3f,top+Vector3.up*14.5f,.95f,new Color(.14f,.25f,.27f),far?6:10);Box(top+Vector3.up*13.6f,new Vector3(.85f,1.2f,.85f),new Color(1,.84f,.43f),.55f);for(int k=0;k<(far?6:12);k++){int sides=far?6:12;float a=k*Mathf.PI*2/sides,b=(k+1)*Mathf.PI*2/sides;Tri(top+new Vector3(Mathf.Cos(a)*1.45f,14.5f,Mathf.Sin(a)*1.45f),top+Vector3.up*16,top+new Vector3(Mathf.Cos(b)*1.45f,14.5f,Mathf.Sin(b)*1.45f),new Color(.21f,.16f,.13f));}return (Mesh)T.GetMethod("Save").Invoke(g,new object[]{far?"Distant coastal lighthouse far":"Distant coastal lighthouse near"});}
static Renderer Child(GameObject root,string name,Mesh mesh,Material mat){var g=new GameObject(name);g.transform.SetParent(root.transform,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;var r=g.AddComponent<MeshRenderer>();r.sharedMaterial=mat;return r;}static Mesh Cliff(bool far,int variant){var combos=new CombineInstance[3];for(int j=0;j<3;j++){string path=far?B+"/Granite beach distant "+((j+variant)%4)+" v2.asset":B+"/Beach granite boulder "+((j+variant)%4)+".asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);var pos=j==0?Vector3.zero:j==1?new Vector3(-17,0,6):new Vector3(15,-1,-9);var scale=j==0?new Vector3(10,8,8):j==1?new Vector3(7,5,7):new Vector3(6,6,7);combos[j]=new CombineInstance{mesh=mesh,transform=Matrix4x4.TRS(pos,Quaternion.Euler(0,j*73+variant*21,0),scale)};}var output=new Mesh{name="Offshore granite connected cliff "+variant+(far?" far":" near")};output.CombineMeshes(combos,true,true);output.RecalculateBounds();output.Optimize();AssetDatabase.CreateAsset(output,D+"/"+output.name+".asset");return output;}
static void Run(){if(AssetDatabase.LoadAssetAtPath<GameObject>(D+"/Offshore Cliff Lighthouse Landmarks.prefab"))throw new Exception("Landmarks already built");Directory.CreateDirectory(D);var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=new GameObject("Offshore Cliff Lighthouse Landmarks");var rockMat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/CoastalTerrain/Crags/Shared Large Granite Faces.mat");var portMat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/YachtPortAtlas/Shared Yacht Yard Atlas.mat");var nearTower=Tower(false);var farTower=Tower(true);var positions=new[]{new Vector3(-840,24,470),new Vector3(-900,24,-40),new Vector3(-865,24,-580),new Vector3(-615,24,-1015)};int totalNear=0,totalFar=0;for(int i=0;i<4;i++){var island=new GameObject("Distant granite cliff lighthouse "+(i+1));var nearRock=Cliff(false,i);var farRock=Cliff(true,i);var nr=Child(island,"Near connected granite cliff",nearRock,rockMat);var nt=Child(island,"Near navigation lighthouse",nearTower,portMat);var fr=Child(island,"Far cliff silhouette",farRock,rockMat);var ft=Child(island,"Far navigation tower",farTower,portMat);var lod=island.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.05f,new[]{nr,nt}),new LOD(.0007f,new[]{fr,ft})});lod.RecalculateBounds();totalNear+=nearRock.triangles.Length/3+nearTower.triangles.Length/3;totalFar+=farRock.triangles.Length/3+farTower.triangles.Length/3;string path=D+"/Distant Granite Cliff Lighthouse "+(i+1)+".prefab";PrefabUtility.SaveAsPrefabAsset(island,path);UnityEngine.Object.DestroyImmediate(island);var inst=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path),root.transform);inst.transform.position=positions[i];inst.transform.rotation=Quaternion.Euler(0,30+i*83,0);inst.transform.localScale=Vector3.one*(.82f+i*.07f);}PrefabUtility.SaveAsPrefabAssetAndConnect(root,D+"/Offshore Cliff Lighthouse Landmarks.prefab",InteractionMode.AutomatedAction);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,new Vector3(-1300,440,-200),new Vector3(-780,35,-180),"Offshore-Cliffs-Lighthouses-Overview"});File.WriteAllText("FinalEnvironmentRoadReview/OffshoreNavigationCliffs.txt","SUCCESS four distant spaced connected granite cliff/lighthouse landmarks; exact existing granite material and shared port atlas material; near/far meshes; all four near triangles="+totalNear+" far triangles="+totalFar+"; 2 renderers per active landmark LOD; no new atlas/material/light/collider; prefab and scene saved.");}}
